// AccessGrant One clause of a rule: somebody, and what they get.
type AccessGrant struct {
	// Access What they get, as written.
	Access string `json:"access"`

	// Kind `allow` and `deny` are an aci's words. `level` is OpenLDAP's: a by
	// clause grants a level, and the first matching rule wins, so a level
	// is neither an allow nor a deny.
	Kind AccessGrantKind `json:"kind"`

	// Subject Who, in the rule's own words: self, users, anonymous, a DN, a group.
	Subject string `json:"subject"`
}

// AccessGrantKind `allow` and `deny` are an aci's words. `level` is OpenLDAP's: a by
// clause grants a level, and the first matching rule wins, so a level
// is neither an allow nor a deny.
type AccessGrantKind string

// AccessReport The access control rules that bear on one entry. Not an evaluation of
// anyone's rights.
type AccessReport struct {
	// AskedAbout The identity Alder put the question about: a DN, or `anonymous`.
	// Added in 1.28.
	//
	// Present whether or not there is a verdict, which is what makes it
	// worth having: `effective` is absent entirely when the server
	// cannot answer or declines, and then nothing else in the response
	// says who was asked about.
	AskedAbout *string `json:"askedAbout,omitempty"`

	// Disclaimer One sentence saying what the report is and is not, so every surface
	// says the same thing.
	Disclaimer string `json:"disclaimer"`
	Dn         string `json:"dn"`

	// Effective What the server itself says an identity may do on this entry, from the
	// Get Effective Rights control (1.19 reads rules; this is the directory's
	// own verdict, added in 1.20). It outranks the rules: the rules are what
	// is written, this is what the server will do.
	Effective *EffectiveRights `json:"effective,omitempty"`

	// RightsNote Why there is no verdict from the server: it cannot answer that
	// question, or it declined this one. Neither is "no rights".
	RightsNote *string      `json:"rightsNote,omitempty"`
	Rules      []AccessRule `json:"rules"`

	// Styles The mechanisms rules were found in, named after the attribute that
	// carries them: `aci`, `olcAccess`.
	Styles []string `json:"styles"`

	// Unread Places rules could live that this session could not read, so the
	// report is not the whole answer. The common one: OpenLDAP keeps its
	// rules in the configuration tree, which usually needs its own
	// identity.
	Unread *[]AccessUnread `json:"unread,omitempty"`
}

// AccessRule defines model for AccessRule.
type AccessRule struct {
	// Applies Whether the rule bears on the entry asked about. `maybe` is an
	// honest answer, not a missing one: a regular expression, a filter or
	// a group membership is something Alder does not evaluate.
	Applies AccessRuleApplies `json:"applies"`
	Grants  *[]AccessGrant    `json:"grants,omitempty"`

	// Index Its position where the server orders them. OpenLDAP consults its
	// rules in this order and stops at the first match.
	Index *int `json:"index,omitempty"`

	// Inherited Written on an ancestor of the entry rather than on it.
	Inherited *bool `json:"inherited,omitempty"`

	// Name What the rule calls itself, where the syntax has a name.
	Name *string `json:"name,omitempty"`

	// Parsed Whether the structure below was read with confidence. False means
	// the raw value is all Alder is willing to say about it.
	Parsed bool `json:"parsed"`

	// Raw The rule exactly as the server holds it.
	Raw string `json:"raw"`

	// Source The entry the rule is written on.
	Source string `json:"source"`

	// Style `aci` or `olcAccess`.
	Style string `json:"style"`

	// Target What a rule is written about, as written.
	Target AccessTarget `json:"target,omitempty"`

	// Why That answer, in a person's words.
	Why *string `json:"why,omitempty"`
}

// AccessRuleApplies Whether the rule bears on the entry asked about. `maybe` is an
// honest answer, not a missing one: a regular expression, a filter or
// a group membership is something Alder does not evaluate.
type AccessRuleApplies string

// AccessTarget What a rule is written about, as written.
type AccessTarget struct {
	// Attributes The attributes the rule narrows to, as written. A leading `!` is
	// kept: an aci's `targetattr!=` excludes rather than includes.
	Attributes *[]string `json:"attributes,omitempty"`
	Dn         *string   `json:"dn,omitempty"`
	Filter     *string   `json:"filter,omitempty"`
	Scope      *string   `json:"scope,omitempty"`
}

// AccessUnread defines model for AccessUnread.
type AccessUnread struct {
	Reason string `json:"reason"`
	Where  string `json:"where"`
}

// AccountState What the server currently records about the account, from its own
// operational attributes.
type AccountState struct {
	Attributes   []PolicySetting `json:"attributes"`
	Changed      *string         `json:"changed,omitempty"`
	Expiry       *string         `json:"expiry,omitempty"`
	Failures     *string         `json:"failures,omitempty"`
	Locked       bool            `json:"locked"`
	LockedDetail *string         `json:"lockedDetail,omitempty"`
	MustChange   bool            `json:"mustChange"`
}

// AccountUnlock The change that would clear the lock on this account. Added in 1.29.
// Present only when the account is locked and Alder knows how to clear
// that kind of lock; a lock it does not recognise gets no change rather
// than an invented one.
//
// This is derived by the server, not the client, for the reason every
// other change is: there is one code path that builds what gets sent,
// and the LDIF the operator confirms is rendered from that record. It is
// an ordinary `ChangeRequest` and goes through the same plan, the same
// review and the same apply as any other write.
type AccountUnlock struct {
	// Attributes The attributes the change removes, in the order it removes them,
	// so a caller can say what it is about to do without reading LDIF.
	Attributes []string      `json:"attributes"`
	Change     ChangeRequest `json:"change"`

	// Why What clearing them means, in a person's words.
	Why string `json:"why"`
}

// ApplyResult defines model for ApplyResult.
type ApplyResult struct {
	Applied bool `json:"applied"`

	// Dn The entry's DN after the change, which differs for a rename.
	Dn   string  `json:"dn"`
	Ldif *string `json:"ldif,omitempty"`

	// Note Present when the change was accepted but Alder could not confirm
	// where the entry ended up.
	Note *string `json:"note,omitempty"`

	// Recovery The recovery bundle, when one was asked for. Added in 1.9.
	Recovery *json.RawMessage `json:"recovery,omitempty"`

	// StoredDn Where the entry actually came to rest, when that is not the DN the
	// change was addressed to.
	//
	// A directory may store an added entry under a different name: where
	// an entry's position among its siblings forms part of that name, the
	// server assigns the position and rewrites the RDN. Reporting the
	// requested DN in that case sends the caller to an entry that is not
	// there.
	StoredDn *string `json:"storedDn,omitempty"`
	Summary  *string `json:"summary,omitempty"`
}

// AttributeComparison defines model for AttributeComparison.
type AttributeComparison struct {
	Left ComparedSide `json:"left"`

	// Name The attribute description, options included. `userCertificate;binary`
	// and `userCertificate` are two rows, not one.
	Name  string       `json:"name"`
	Right ComparedSide `json:"right"`

	// Status `withheld` means both entries hold the attribute and it was not
	// compared, because it is sensitive. It is a status of its own rather
	// than `same` with a flag beside it: a client reading only this field
	// must not be able to conclude that two passwords match.
	//
	// `undetermined` means the access rules stopped the comparison. The
	// attribute is on one side and was not returned for the other, and
	// asking the server directly said the bind may not look rather than
	// that the entry lacks it. Reporting that as `leftOnly` would be a
	// statement about the directory that this session has no basis for.
	// The side that could not be read carries `denied`.
	Status    AttributeComparisonStatus `json:"status"`
	Truncated *bool                     `json:"truncated,omitempty"`

	// Values Absent for a withheld attribute.
	Values *[]ValueComparison `json:"values,omitempty"`

	// Withheld Sensitive, so no value crosses the wire from either side. Presence
	// is still reported on each side, because `/entry` already says whether
	// a password is set. Equality is not: reporting whether two entries
	// hold the same password hash would be an oracle about password
	// material the product offers nowhere else.
	Withheld *bool `json:"withheld,omitempty"`
}

// AttributeComparisonStatus `withheld` means both entries hold the attribute and it was not
// compared, because it is sensitive. It is a status of its own rather
// than `same` with a flag beside it: a client reading only this field
// must not be able to conclude that two passwords match.
//
// `undetermined` means the access rules stopped the comparison. The
// attribute is on one side and was not returned for the other, and
// asking the server directly said the bind may not look rather than
// that the entry lacks it. Reporting that as `leftOnly` would be a
// statement about the directory that this session has no basis for.
// The side that could not be read carries `denied`.
type AttributeComparisonStatus string

// AttributeKind The schema's opinion about one attribute, for the editor.
type AttributeKind struct {
	Desc *string `json:"desc,omitempty"`

	// Elsewhere Why the entry editor does not offer this attribute, in a sentence
	// fit to print beside it.
	//
	// Its absence is not a promise that the attribute is editable:
	// `readOnly`, a withheld secret and a binary value each keep a field
	// off the screen for their own reasons. Present means Alder has
	// decided, whatever the server would allow.
	//
	// Distinct from `readOnly`, which is the server's refusal. This is
	// Alder's: an access rule is read and never authored in the editor
	// (a reviewed change or a recovery bundle that carries one is applied,
	// with a warning), and a schema definition is written by the schema
	// editor one definition at a time rather than by replacing a
	// thousand of them in a text box.
	Elsewhere *string           `json:"elsewhere,omitempty"`
	Kind      AttributeKindKind `json:"kind"`

	// Known False when the schema does not define this attribute.
	Known       bool    `json:"known"`
	MaxLength   *int    `json:"maxLength,omitempty"`
	Name        string  `json:"name"`
	Obsolete    *bool   `json:"obsolete,omitempty"`
	Oid         *string `json:"oid,omitempty"`
	Operational *bool   `json:"operational,omitempty"`

	// ReadOnly NO-USER-MODIFICATION; the server owns this value.
	ReadOnly *bool `json:"readOnly,omitempty"`

	// Sensitive A secret. Values are withheld and never logged.
	Sensitive   *bool   `json:"sensitive,omitempty"`
	SingleValue *bool   `json:"singleValue,omitempty"`
	Syntax      *string `json:"syntax,omitempty"`
	SyntaxLabel *string `json:"syntaxLabel,omitempty"`
}

// AttributeKindKind defines model for AttributeKind.Kind.
type AttributeKindKind string

