// ExportLdifParams defines parameters for ExportLdif.
type ExportLdifParams struct {
	Dn    string                 `form:"dn" json:"dn"`
	Scope *ExportLdifParamsScope `form:"scope,omitempty" json:"scope,omitempty"`

	// IncludeOperational Operational attributes cannot be written back, so they are off by default.
	IncludeOperational *bool `form:"includeOperational,omitempty" json:"includeOperational,omitempty"`

	// IncludeSensitive Password hashes and similar are omitted unless this is set. An LDIF
	// export ends up in tickets and repositories.
	IncludeSensitive *bool `form:"includeSensitive,omitempty" json:"includeSensitive,omitempty"`

	// Filter An RFC 4515 filter, defaulting to `(objectClass=*)`. It is parsed
	// here, never pasted, exactly as the search filter is.
	//
	// It exists so a table can export what it is showing. Without it the
	// only exports available are one entry, or a whole subtree, and
	// "the thirty people I just searched for" — which is what somebody
	// actually wants to put in a ticket or a repository — could only be
	// assembled by hand.
	Filter *string `form:"filter,omitempty" json:"filter,omitempty"`

	// Limit The document is streamed and rendered a page at a time, so this
	// bounds how long the export runs rather than how much it holds.
	Limit *int `form:"limit,omitempty" json:"limit,omitempty"`

	// Attributes Comma-separated attribute names to export, such as `uid,cn,mail`.
	// Omitted, every user attribute is, as before. A sensitive attribute
	// named here is still left out unless `includeSensitive` is set, and
	// `includeOperational` still adds the operational ones. At most 100
	// names.
	Attributes *string `form:"attributes,omitempty" json:"attributes,omitempty"`
}

